import{_ as e,o,c as r,a2 as n}from"./chunks/framework.CjAa9jTu.js";const t="/unit_devlab_cortex_m_examples/py32f003/conexion-swd.jpeg",i="/unit_devlab_cortex_m_examples/py32f003/carga-firmware.png",h=JSON.parse('{"title":"Programación mediante SWD","description":"","frontmatter":{},"headers":[],"relativePath":"py32f003-getting-started/04_swd.md","filePath":"py32f003-getting-started/04_swd.md"}'),c={name:"py32f003-getting-started/04_swd.md"};function l(s,a,d,p,m,u){return o(),r("div",null,[...a[0]||(a[0]=[n(`<h1 id="programacion-mediante-swd" tabindex="-1">Programación mediante SWD <a class="header-anchor" href="#programacion-mediante-swd" aria-label="Permalink to &quot;Programación mediante SWD&quot;">​</a></h1><h2 id="que-hace-cada-componente" tabindex="-1">Qué hace cada componente <a class="header-anchor" href="#que-hace-cada-componente" aria-label="Permalink to &quot;Qué hace cada componente&quot;">​</a></h2><p><strong>Arduino IDE</strong> compila el código. <strong>pyOCD</strong> envía el firmware al programador. <strong>CMSIS-DAP</strong> es el protocolo entre la computadora y el programador; <strong>SWD</strong> es la interfaz que llega al microcontrolador por SWDIO y SWCLK.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Archivo .ino → compilador ARM → firmware .hex</span></span>
<span class="line"><span>                                   ↓</span></span>
<span class="line"><span>                         pyOCD → USB → CMSIS-DAP</span></span>
<span class="line"><span>                                           ↓ SWDIO / SWCLK</span></span>
<span class="line"><span>                                      PY32F003</span></span></code></pre></div><h2 id="conexiones" tabindex="-1">Conexiones <a class="header-anchor" href="#conexiones" aria-label="Permalink to &quot;Conexiones&quot;">​</a></h2><p>Realiza el cableado con la alimentación desconectada y el programador ya configurado en modo CMSIS-DAP.</p><table tabindex="0"><thead><tr><th>Programador</th><th>Placa DevLab</th><th>Función</th></tr></thead><tbody><tr><td>GND</td><td>GND</td><td>Referencia común</td></tr><tr><td>Alimentación o referencia de destino, según el modelo</td><td>VCC</td><td>Estación configurada a 3.3 V</td></tr><tr><td>SWDIO</td><td>SWDIO / PA13</td><td>Datos</td></tr><tr><td>SWCLK</td><td>SWCLK / PA14</td><td>Reloj</td></tr></tbody></table><ol><li>Verifica la <a href="./01_setup#alimentacion-de-referencia">alimentación de la estación</a>.</li><li>Comprueba la correspondencia de las cuatro señales en ambos extremos del cable.</li><li>Conecta el programador a la computadora mediante un cable USB de datos.</li><li>Ejecuta <code>pyocd list</code> y confirma que aparece el programador.</li></ol><p><img src="`+t+'" alt="Ejemplo de conexión de DevLab al programador CH552"></p><p>La fotografía muestra el montaje de referencia de Development Board. Comprueba los selectores de tu estación para trabajar a 3.3 V.</p><h2 id="cargar-el-programa" tabindex="-1">Cargar el programa <a class="header-anchor" href="#cargar-el-programa" aria-label="Permalink to &quot;Cargar el programa&quot;">​</a></h2><p>En Arduino IDE selecciona <strong>PY32F003x4</strong> y <strong>CMSIS-DAP (pyOCD)</strong>, verifica el programa y pulsa <strong>Subir</strong>. El paquete 0.1.7 utiliza su archivo <code>Misc/Puya.PY32.pack</code> para que pyOCD reconozca el dispositivo y programe la Flash. No se necesita instalar un bootloader para este flujo.</p><p><img src="'+i+'" alt="Salida de programación en Arduino IDE"></p><p>La carga correcta confirma la comunicación y la escritura del firmware. Comprueba después el comportamiento de la <a href="./../examples/lab01-blink">práctica Blink</a>. Si la ejecución no comienza al terminar la carga, pulsa RESET.</p><h2 id="recuperacion-basica" tabindex="-1">Recuperación básica <a class="header-anchor" href="#recuperacion-basica" aria-label="Permalink to &quot;Recuperación básica&quot;">​</a></h2><ol><li>Confirma la alimentación y la presencia del programador con <code>pyocd list</code>.</li><li>Retira accesorios de las líneas compartidas SWD/I²C con la estación apagada.</li><li>Vuelve a conectar y carga el ejemplo <code>01_blink</code> conocido.</li><li>Pulsa RESET y comprueba el parpadeo.</li></ol><p>Los ejemplos de este taller conservan las líneas SWD y no modifican los option bytes del microcontrolador. Si el firmware de otra práctica cambió esas funciones, el instructor debe revisar el procedimiento de conexión bajo reset para su programador antes de continuar.</p><h2 id="programacion-desde-el-navegador" tabindex="-1">Programación desde el navegador <a class="header-anchor" href="#programacion-desde-el-navegador" aria-label="Permalink to &quot;Programación desde el navegador&quot;">​</a></h2><p>El plan de la actividad contempla WebUSB como posibilidad para las estaciones. Esta guía usa <strong>Arduino IDE + pyOCD</strong>, un flujo concreto incluido en el paquete PY32. Una demostración de WebUSB requiere que el instructor prepare y pruebe una herramienta compatible con PY32F003 y con el programador disponible.</p><p><strong>Ayuda:</strong> <a href="./report">Solución de problemas</a>.</p>',20)])])}const b=e(c,[["render",l]]);export{h as __pageData,b as default};
